#pragma warning disable CA1725
using Microsoft.EntityFrameworkCore;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Domain.Inventory;
namespace WhatsBiz.Infrastructure.Persistence;
public sealed class InventoryRepository(ApplicationDbContext db):IInventoryRepository{public async Task<(IReadOnlyCollection<InventoryBalance>,int)> Balances(string? search,Guid? warehouseId,Guid? productId,int page,int size,CancellationToken token){var q=db.InventoryBalances.AsNoTracking().Include(x=>x.Product).Include(x=>x.Warehouse).Include(x=>x.Zone).Include(x=>x.Bin).AsQueryable();if(warehouseId.HasValue)q=q.Where(x=>x.WarehouseId==warehouseId);if(productId.HasValue)q=q.Where(x=>x.ProductId==productId);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Product.ProductCode.Contains(search)||x.Product.ProductName.Contains(search)||(x.BatchNo!=null&&x.BatchNo.Contains(search))||(x.SerialNo!=null&&x.SerialNo.Contains(search)));var count=await q.CountAsync(token);var rows=await q.OrderBy(x=>x.Product.ProductName).ThenBy(x=>x.Warehouse.WarehouseName).Skip((Math.Max(page,1)-1)*Math.Clamp(size,1,200)).Take(Math.Clamp(size,1,200)).ToArrayAsync(token);return(rows,count);}public async Task<(IReadOnlyCollection<InventoryTransaction>,int)> Transactions(string? search,Guid? warehouseId,string? type,DateTimeOffset? from,DateTimeOffset? to,int page,int size,CancellationToken token){var q=db.InventoryTransactions.AsNoTracking().Include(x=>x.Warehouse).Include(x=>x.Details).AsQueryable();if(warehouseId.HasValue)q=q.Where(x=>x.WarehouseId==warehouseId);if(!string.IsNullOrWhiteSpace(type))q=q.Where(x=>x.TransactionType==type);if(from.HasValue)q=q.Where(x=>x.TransactionDate>=from);if(to.HasValue)q=q.Where(x=>x.TransactionDate<=to);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.TransactionNo.Contains(search)||(x.ReferenceType!=null&&x.ReferenceType.Contains(search)));var count=await q.CountAsync(token);return(await q.OrderByDescending(x=>x.TransactionDate).Skip((Math.Max(page,1)-1)*Math.Clamp(size,1,200)).Take(Math.Clamp(size,1,200)).ToArrayAsync(token),count);}public Task<InventoryTransaction?> Transaction(Guid id,CancellationToken token)=>db.InventoryTransactions.AsNoTracking().Include(x=>x.Warehouse).Include(x=>x.Details).ThenInclude(x=>x.Product).SingleOrDefaultAsync(x=>x.TransactionId==id,token);public async Task<IReadOnlyCollection<StockReservation>> Reservations(Guid? warehouseId,Guid? productId,CancellationToken token){var q=db.StockReservations.AsNoTracking().AsQueryable();if(warehouseId.HasValue)q=q.Where(x=>x.WarehouseId==warehouseId);if(productId.HasValue)q=q.Where(x=>x.ProductId==productId);return await q.OrderByDescending(x=>x.CreatedOn).Take(500).ToArrayAsync(token);}public async Task<InventorySummary> Summary(Guid? warehouseId,CancellationToken token){var q=db.InventoryBalances.AsNoTracking().AsQueryable();if(warehouseId.HasValue)q=q.Where(x=>x.WarehouseId==warehouseId);var total=await q.SumAsync(x=>(decimal?)x.QuantityOnHand,token)??0;var value=await q.SumAsync(x=>(decimal?)(x.QuantityOnHand*x.AverageCost),token)??0;var reserved=await q.SumAsync(x=>(decimal?)x.QuantityReserved,token)??0;var products=q.GroupBy(x=>new{x.ProductId,x.Product.ReorderLevel}).Select(x=>new{Quantity=x.Sum(y=>y.QuantityAvailable),x.Key.ReorderLevel});var outOfStock=await products.CountAsync(x=>x.Quantity<=0,token);var low=await products.CountAsync(x=>x.Quantity>0&&x.Quantity<=x.ReorderLevel,token);return new(total,value,reserved,low,outOfStock);}}
